#!/bin/bash
sed -i 's/_uiState.value = PlayerUiState.Success(bundle.title, bundle.uploaderName, bundle)/_uiState.value = PlayerUiState.Success(bundle, currentVideoItem!!, bundle.relatedVideos, bundle.nextRelatedVideosPage != null, bundle.nextRelatedVideosPage)/g' app/src/main/java/com/rahul/vibetube/ui/screens/player/PlayerViewModel.kt
sed -i 's/fetchRelatedShorts(videoId, bundle)//g' app/src/main/java/com/rahul/vibetube/ui/screens/player/PlayerViewModel.kt
sed -i 's/_uiState.value = PlayerUiState.Success(downloadedVideo.title, downloadedVideo.uploaderName, localBundle)/_uiState.value = PlayerUiState.Success(localBundle, VideoItem(id = videoId, title = downloadedVideo.title, thumbnailUrl = downloadedVideo.thumbnailUrl, uploaderName = downloadedVideo.uploaderName, uploaderUrl = null, uploaderThumbnailUrl = null, viewCount = 0, uploadDate = null, rawUploadDate = null, duration = 0), emptyList(), false)/g' app/src/main/java/com/rahul/vibetube/ui/screens/player/PlayerViewModel.kt
sed -i 's/_uiState.value = PlayerUiState.Success(video.title, video.uploaderName, placeholderBundle)/_uiState.value = PlayerUiState.Success(placeholderBundle, video, emptyList(), false)/g' app/src/main/java/com/rahul/vibetube/ui/screens/player/PlayerViewModel.kt
sed -i 's/_uiState.value = PlayerUiState.Success(currentState.title, currentState.uploader, updatedBundle)/_uiState.value = PlayerUiState.Success(updatedBundle, currentState.details, currentState.relatedStreams, currentState.hasNextPage, currentState.nextTrendingPage)/g' app/src/main/java/com/rahul/vibetube/ui/screens/player/PlayerViewModel.kt
